from __future__ import annotations; import re; from pathlib import Path; ROOT = Path(__file__).resolve().parents[2]; OBSERVABILITY_DOC = ROOT / 'common' / 'observability' / 'observability.md'; ENVIRONMENTS_DOC = ROOT / 'common' / 'runtime' / 'environments.md'; CONFIG_PY = ROOT / 'apps' / 'backend' / 'src' / 'config.py'; OPS_OBSERVABILITY_POINTER = 'https://github.com/wangzitian0/infra2/blob/main/docs/ssot/ops.observability.md'; CORE_ENVIRONMENTS_POINTER = 'https://github.com/wangzitian0/infra2/blob/main/docs/ssot/core.environments.md'; WRONG_DEPLOYMENT_ENV_RE = re.compile('deployment\\.environment=prod(?![A-Za-z0-9_])'); PER_ENV_COLLECTOR_FORM = 'platform-signoz-otel-collector${ENV_SUFFIX}'
def _read(path: Path) -> str: assert path.exists(), f'expected file to exist: {path}'; return path.read_text(encoding='utf-8')
def test_observability_doc_points_to_infra2_contract() -> None:
    text = _read(OBSERVABILITY_DOC); assert OPS_OBSERVABILITY_POINTER in text, f'common/observability/observability.md must point at the infra2-owned contract ({OPS_OBSERVABILITY_POINTER})'; assert CORE_ENVIRONMENTS_POINTER in text, f'common/observability/observability.md must point at the infra2-owned contract ({CORE_ENVIRONMENTS_POINTER})'; _m1_text = _read(ENVIRONMENTS_DOC); assert OPS_OBSERVABILITY_POINTER in _m1_text, f'common/runtime/environments.md must point at the infra2-owned contract ({OPS_OBSERVABILITY_POINTER})'; assert CORE_ENVIRONMENTS_POINTER in _m1_text, f'common/runtime/environments.md must point at the infra2-owned contract ({CORE_ENVIRONMENTS_POINTER})'
    for _m2_doc in (OBSERVABILITY_DOC, ENVIRONMENTS_DOC): _m2_text = _read(_m2_doc); assert WRONG_DEPLOYMENT_ENV_RE.search(_m2_text) is None, f"{_m2_doc.relative_to(ROOT)} re-introduced the wrong contract value 'deployment.environment=prod'; the App must not restate deployment.environment values (infra2 owns them)."; assert PER_ENV_COLLECTOR_FORM not in _m2_text, f"{_m2_doc.relative_to(ROOT)} re-introduced a per-env collector endpoint '{PER_ENV_COLLECTOR_FORM}'; the App must not restate collector endpoints (infra2 owns the single no-suffix collector)."
    _m3_text = _read(CONFIG_PY); assert 'openpanel_clients' not in _m3_text, "apps/backend/src/config.py must not hardcode a per-env 'openpanel_clients' map; per-env OpenPanel client ids are issued by infra2 (they live in infra2 deploy tooling, not the App config)."
def test_AC10_9_5_app_side_snapshot_is_retired() -> None: 'AC-observability.9.4 AC10.9.5'; assert not (ROOT / 'tools' / 'dokploy_failure_snapshot.py').exists()
